@import '../../utils/chrome-header.css';
@import '../../utils/chrome-layout.css';
@import '../../utils/forced-colors.css';

:host {
  display: contents;
}

.modal-dialog {
  display: none;
  flex-direction: column;
  max-width: none;
  max-height: calc(100vh - 2 * var(--dimension-space-200));
  margin: auto;
  padding: 0;
  overflow: hidden;
  color: var(--color-foreground-primary);
  background-color: var(--color-background-primary);
  border: 0;
  border-radius: var(--dimension-radius-050);
  box-shadow: var(--effect-elevation-elevated-floating);
  outline: none;
  box-sizing: border-box;
  animation: modalDialogIn var(--effect-motion-short-2) forwards;
}

.modal-dialog[open] {
  display: flex;
}

.modal-dialog::backdrop {
  background-color: var(--color-background-shade);
  animation: modalBackdropIn var(--effect-motion-short-2) forwards;
}

.modal-dialog--closing {
  animation: modalDialogOut var(--effect-motion-short-2) forwards;
}

.modal-dialog--closing::backdrop {
  animation: modalBackdropOut var(--effect-motion-short-2) forwards;
}

@keyframes modalBackdropIn {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes modalBackdropOut {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}

@keyframes modalDialogIn {
  from {
    opacity: 0;
    transform: scale(0.97) translateY(4px);
  }
  to {
    opacity: 1;
    transform: scale(1) translateY(0);
  }
}

@keyframes modalDialogOut {
  from {
    opacity: 1;
    transform: scale(1) translateY(0);
  }
  to {
    opacity: 0;
    transform: scale(0.97) translateY(4px);
  }
}

@media (prefers-reduced-motion: reduce) {
  .modal-dialog[open],
  .modal-dialog--closing {
    animation: none;
    transform: none;
  }

  .modal-dialog::backdrop {
    animation: none;
    opacity: 1;
  }

  .modal-dialog--closing,
  .modal-dialog--closing::backdrop {
    opacity: 0;
  }
}

.modal-header {
  align-items: flex-start;
  flex: 0 0 auto;
  color: var(--color-foreground-primary);
}

.modal-copy,
ds-text.modal-heading,
ds-text.modal-description {
  width: auto;
  text-align: left;
}

ds-text.modal-heading {
  -webkit-user-select: none;
  user-select: none;
}

.modal-close-tooltip {
  flex: 0 0 auto;
}

.modal-content {
  min-height: 0;
  padding: var(--dimension-space-200);
  overflow-y: auto;
  flex: 1 1 auto;
  box-sizing: border-box;
}

.modal-footer {
  justify-content: flex-start;
  height: var(--dimension-size-800);
  flex: 0 0 auto;
  border-top: var(--dimension-stroke-width-012) solid var(--color-border-tertiary);
}

.modal-footer__actions {
  display: flex;
  align-items: center;
  gap: var(--dimension-space-100);
  min-width: 0;
}

.modal-footer--empty {
  display: none;
}

.modal-footer__actions slot {
  display: contents;
}

@media (forced-colors: active) {
  .modal-dialog {
    box-shadow: none;
    outline: var(--dimension-stroke-width-012) solid var(--ds-forced-color-content);
    outline-offset: calc(-1 * var(--dimension-stroke-width-012));
  }
}

import {
  Component,
  Prop,
  State,
  Event,
  EventEmitter,
  Element,
  Watch,
  h,
  Host,
} from '@stencil/core';
import { resolveMotionTimeMs, TOKEN_DEFAULTS } from '../../utils';

export type ModalWidth = 'sm' | 'md' | 'lg';
export type ModalCloseReason = 'close-button' | 'escape' | 'backdrop';

export interface ModalCloseDetail {
  reason: ModalCloseReason;
  originalEvent: Event;
}

const WIDTH_MAP: Record<ModalWidth, string> = {
  sm: 'var(--dimension-modal-width-sm)',
  md: 'var(--dimension-modal-width-md)',
  lg: 'var(--dimension-modal-width-lg)',
};

const FOCUSABLE_SEL = [
  'a[href]',
  'area[href]',
  'button:not([disabled])',
  'input:not([disabled]):not([type="hidden"])',
  'select:not([disabled])',
  'textarea:not([disabled])',
  'iframe',
  '[contenteditable="true"]',
  '[tabindex]:not([tabindex="-1"])',
].join(',');

let modalIdCounter = 0;

@Component({
  tag: 'ds-modal',
  styleUrl: 'Modal.css',
  scoped: true,
})
export class Modal {
  @Element() el!: HTMLElement;

  @Prop({ mutable: true }) open: boolean = false;
  @Prop() heading!: string;
  /** Optional supporting copy shown below the heading. */
  @Prop() description: string = '';
  @Prop() closeAriaLabel: string = 'Close';
  @Prop() modalWidth: ModalWidth | string = 'md';
  /** Optional id reference for explanatory content in the default slot. */
  @Prop({ attribute: 'aria-describedby' }) ariaDescribedby: string | undefined;

  @State() private closing: boolean = false;
  @State() private hasFooter: boolean = false;

  /** Emitted when an internal dismissal control requests that the modal close. */
  @Event() dsClose!: EventEmitter<ModalCloseDetail>;
  /** Emitted after exit motion completes, the top layer closes, and focus is restored. */
  @Event() dsAfterClose!: EventEmitter<void>;

  private titleId = `ds-modal-title-${++modalIdCounter}`;
  private descriptionId = `${this.titleId}-description`;
  private dialogEl: HTMLDialogElement | null = null;
  private previousFocus: HTMLElement | null = null;
  private closeTimer: ReturnType<typeof setTimeout> | null = null;

  componentDidLoad() {
    this.updateFooterPresence();
    if (this.open) this.onOpenChange(true);
  }

  componentDidRender() {
    if (!this.closing || !this.dialogEl?.open || this.closeTimer) return;
    const closeAnimationMs = this.closeAnimationMs;
    if (closeAnimationMs <= 0) {
      this.finishClose();
      return;
    }
    this.closeTimer = setTimeout(() => {
      this.closeTimer = null;
      this.finishClose();
    }, closeAnimationMs);
  }

  disconnectedCallback() {
    this.clearCloseTimer();
    if (this.dialogEl?.open) this.dialogEl.close();
  }

  @Watch('open')
  onOpenChange(isOpen: boolean) {
    if (isOpen) {
      this.clearCloseTimer();
      const alreadyOpen = !!this.dialogEl?.open;
      this.closing = false;
      if (!this.dialogEl || alreadyOpen) return;
      this.previousFocus = document.activeElement as HTMLElement | null;
      this.dialogEl.showModal();
      requestAnimationFrame(() => {
        if (this.open && this.dialogEl?.open) this.focusClose();
      });
    } else if (this.dialogEl?.open) {
      this.closing = true;
    }
  }

  private focusClose() {
    const close = this.el.querySelector('ds-button-unfilled.modal-close') as
      | (HTMLElement & { setFocus?: () => Promise<void> })
      | null;
    void close?.setFocus?.();
  }

  private clearCloseTimer() {
    if (this.closeTimer) {
      clearTimeout(this.closeTimer);
      this.closeTimer = null;
    }
  }

  private requestClose(reason: ModalCloseReason, originalEvent: Event) {
    if (!this.open || this.closing || !this.dialogEl?.open) return;
    this.dsClose.emit({ reason, originalEvent });
    this.open = false;
  }

  private updateFooterPresence(slot?: HTMLSlotElement) {
    const assignedNodes = slot?.assignedNodes() ?? [];
    this.hasFooter =
      assignedNodes.some(node => node.nodeType !== Node.TEXT_NODE || !!node.textContent?.trim()) ||
      this.el.querySelector('[slot="footer"]') !== null;
  }

  private handleCancel(event: Event) {
    event.preventDefault();
    this.requestClose('escape', event);
  }

  private handleBackdropPointerDown(event: PointerEvent) {
    if (event.target === this.dialogEl) this.requestClose('backdrop', event);
  }

  private handleKeyDown(event: KeyboardEvent) {
    if (event.key === 'Escape') {
      event.preventDefault();
      this.requestClose('escape', event);
      return;
    }
    if (event.key !== 'Tab' || !this.dialogEl) return;
    const focusables = Array.from(
      this.dialogEl.querySelectorAll<HTMLElement>(FOCUSABLE_SEL)
    ).filter(
      element => !element.hasAttribute('disabled') && element.getAttribute('aria-hidden') !== 'true'
    );
    if (!focusables.length) {
      event.preventDefault();
      this.dialogEl.focus();
      return;
    }
    const first = focusables[0];
    const last = focusables[focusables.length - 1];
    const active = document.activeElement;
    if (event.shiftKey && (active === first || active === this.dialogEl)) {
      event.preventDefault();
      last.focus();
    } else if (!event.shiftKey && active === last) {
      event.preventDefault();
      first.focus();
    }
  }

  private get resolvedWidth(): string {
    if (this.modalWidth === 'sm' || this.modalWidth === 'md' || this.modalWidth === 'lg') {
      return WIDTH_MAP[this.modalWidth];
    }
    return this.modalWidth as string;
  }

  private get describedBy(): string | undefined {
    const ids = [this.description ? this.descriptionId : '', this.ariaDescribedby ?? ''].filter(
      Boolean
    );
    return ids.length > 0 ? ids.join(' ') : undefined;
  }

  private get closeAnimationMs(): number {
    return resolveMotionTimeMs(TOKEN_DEFAULTS.motionShort2, TOKEN_DEFAULTS.animationDurationShort3);
  }

  private finishClose() {
    if (!this.dialogEl?.open) return;
    this.dialogEl.close();
    this.closing = false;
    this.clearCloseTimer();
    this.previousFocus?.focus?.();
    this.previousFocus = null;
    this.dsAfterClose.emit();
  }

  render() {
    return (
      <Host>
        <dialog
          ref={(element?: HTMLDialogElement) => {
            this.dialogEl = element ?? null;
          }}
          class={{ 'modal-dialog': true, 'modal-dialog--closing': this.closing }}
          aria-labelledby={this.titleId}
          aria-describedby={this.describedBy}
          onCancel={(event: Event) => this.handleCancel(event)}
          onPointerDown={(event: PointerEvent) => this.handleBackdropPointerDown(event)}
          onKeyDown={(event: KeyboardEvent) => this.handleKeyDown(event)}
          style={{
            width: `min(${this.resolvedWidth}, calc(100vw - 2 * var(--dimension-space-200)))`,
          }}
        >
          <div class="modal-header ds-chrome-header ds-chrome-header--bounded">
            <div class="modal-copy ds-chrome-header__copy ds-chrome-header__copy--stacked ds-control--md">
              <ds-text
                class="modal-heading ds-chrome-header__heading"
                as="h2"
                variant="text-title-small"
                emphasis
                color="primary"
                lineTruncation={1}
                textId={this.titleId}
              >
                {this.heading}
              </ds-text>
              {this.description ? (
                <ds-text
                  class="modal-description ds-chrome-header__description"
                  as="p"
                  variant="text-body-medium"
                  color="secondary"
                  wrap="wrap"
                  textId={this.descriptionId}
                >
                  {this.description}
                </ds-text>
              ) : null}
            </div>
            <ds-tooltip
              class="modal-close-tooltip ds-chrome-header__trailing"
              label={this.closeAriaLabel}
              side="bottom"
              size="sm"
            >
              <ds-button-unfilled
                class="modal-close"
                variant="icon"
                icon="Cross"
                size="md"
                aria-label={this.closeAriaLabel}
                activeFill={false}
                hasBorder={false}
                onDsClick={(event: CustomEvent<MouseEvent>) =>
                  this.requestClose('close-button', event.detail)
                }
              />
            </ds-tooltip>
          </div>
          <div class="modal-content">
            <slot />
          </div>
          <div
            class={{
              'modal-footer': true,
              'ds-chrome-row': true,
              'ds-chrome-space--lg': true,
              'modal-footer--empty': !this.hasFooter,
            }}
          >
            <div class="modal-footer__actions">
              <slot
                name="footer"
                onSlotchange={(event: Event) =>
                  this.updateFooterPresence(event.currentTarget as HTMLSlotElement)
                }
              />
            </div>
          </div>
        </dialog>
      </Host>
    );
  }
}
